package cl.duoc.bancoxyz.payments.service;
import cl.duoc.bancoxyz.payments.dto.PaymentRequest; import cl.duoc.bancoxyz.payments.event.DomainEventPublisher; import cl.duoc.bancoxyz.payments.model.Payment; import cl.duoc.bancoxyz.payments.repository.PaymentRepository; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class PaymentProcessingServiceTest { @Test void reusesAnExistingOperation(){PaymentRepository r=mock(PaymentRepository.class);DomainEventPublisher events=mock(DomainEventPublisher.class);Payment p=new Payment("op-1",1L,2L,new BigDecimal("500"),"TRANSFER");when(r.findByOperationId("op-1")).thenReturn(Optional.of(p));var response=new PaymentProcessingService(r,events).process(new PaymentRequest("op-1",1L,2L,new BigDecimal("500"),"transfer"));assertThat(response.operationId()).isEqualTo("op-1");verify(r,never()).save(any());verifyNoInteractions(events);} }
